	@Test
	void namedGraphKeepsCorrelationAcrossActiveGraphContext() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			connection.add(vf.createIRI("urn:noise"), vf.createIRI("urn:q"), vf.createIRI("urn:object"),
					vf.createIRI("urn:g"));
			assertRows(connection.prepareTupleQuery("SELECT ?x { VALUES ?x { <urn:missing> } "
					+ "FILTER EXISTS { GRAPH <urn:g> { ?x <urn:p>* ?x } } }"), 1);
			assertRows(connection.prepareTupleQuery("SELECT ?x { VALUES ?x { <urn:missing> } "
					+ "GRAPH <urn:g> { ?x <urn:p>* ?x } }"), 0);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void repeatedPreparedInvocationsDoNotLeakSubstitutionBindings() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery("SELECT ?x { FILTER EXISTS { ?x <urn:p>* ?x } }");
			query.setBinding("x", SimpleValueFactory.getInstance().createIRI("urn:first"));
			assertRows(query, 1);
			query.clearBindings();
			assertRows(query, 0);
			query.setBinding("x", SimpleValueFactory.getInstance().createLiteral("second"));
			assertRows(query, 1);
		} finally {
			repository.shutDown();
		}
	}

